"""Render docs/qa/LATENCY_REPORT.md from results/p3/*.json (no number is typed by hand)."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
P3 = ROOT / "results" / "p3"
f = lambda v, d=2: "n/a" if v is None else f"{v:.{d}f}"
L = ["# Latency report (Level 5.1)", "",
     "Generated by `benchmarks/latency_report.py` from `results/p3/*.json`. Conditions, sample sizes and the clock caveats are part of every figure; nothing is extrapolated and nothing was improved by dropping ticks or skipping risk checks.", ""]
e = json.loads((P3 / "e2e_latency.json").read_text(encoding="utf-8"))
L += [f"## End to end in real Chrome (`benchmarks/e2e_latency.mjs`, Chrome {e['chrome']}, {e['seconds_per_scenario']} s per scenario, live MetaQuotes-Demo, server UTC offset {e['server_utc_offset_s']} s)", "",
      "gateway = receipt-to-publish inside the gateway (monotonic clock). delivery = browser receipt minus gateway publish wall clock (same host clock: no skew). render = next paint minus browser receipt. All in ms.", "",
      "| Scenario | frames | frames/s | max gap between frames (ms) | gateway p50 / p95 / p99 | delivery p50 / p95 / p99 | render p50 / p95 / p99 |", "|---|---|---|---|---|---|---|"]
for k, v in e["scenarios"].items():
    g, d, r = v["gateway_ms"], v["delivery_ms"], v["render_ms"]
    L.append(f"| {k} | {v['frames']} | {v['frames_per_s']} | {v['max_gap_between_frames_ms']} | {f(g['p50'])} / {f(g['p95'])} / {f(g['p99'])} | {f(d['p50'])} / {f(d['p95'])} / {f(d['p99'])} | {f(r['p50'], 0)} / {f(r['p95'], 0)} / {f(r['p99'], 0)} |")
m = e["scenarios"]["foreground"]["market_ms_incl_clock_skew"]
L += ["", f"Market leg (gateway receipt minus the tick's server stamp, converted with the measured offset): p50 {f(m['p50'], 0)} ms, i.e. NEGATIVE: the broker's tick stamp is ahead of this PC's clock by roughly 0.3 s or more. The two clocks are not synchronised, so the broker-to-PC latency cannot be derived from these timestamps and none is claimed.",
      f"A hidden tab renders late by design (the browser pauses animation frames): background_tab render p50/p95 above. The 100-drawings scenario is measured after a 10 s settle (the first seconds after a reload are slower: history fetch plus drawings). CPU load: {e['cpu_burners']} busy processes on {e['cpu_cores']} logical cores.", ""]
for name, title in (("gil_contention.json", "50 Hz"), ("gil_contention_burst300hz.json", "300 Hz burst")):
    p = P3 / name
    if not p.exists():
        continue
    g = json.loads(p.read_text(encoding="utf-8"))
    L += [f"## GIL contention, {title} (`benchmarks/gil_contention.py`, {g['seconds']} s per scenario, Python {g['python']}, one `compute_heavy` takes {g['one_compute_heavy_s']:.2f} s)", "",
          "Scheduling delay of a hot-path loop (candle update + JSON) while heavy analysis runs. `n` below the planned count means the loop fell behind and skipped slots.", "",
          "| Layout | n | scheduling delay p50 / p95 / p99 / max (ms) | processing p99 (ms) |", "|---|---|---|---|"]
    for s in g["scenarios"]:
        d, p_ = s["scheduling_delay_ms"], s["processing_ms"]
        nm = s["name"].replace("(production layout)", "(PREVIOUS layout)").replace("in a separate process", "in a separate process (CURRENT production layout)")
        L.append(f"| {nm} | {s['n']} | {f(d['p50'])} / {f(d['p95'])} / {f(d['p99'])} / {f(d['max'])} | {f(p_['p99'])} |")
    L.append("")
L += ["## Reading this honestly", "",
      "- The earlier 29 ms gateway p99 after a restart is explained by the in-process heavy recompute (scheduling delay p99 16-20 ms, max 27 ms here); with the worker process the same loop shows p99 about 0.1 ms. Production now uses the worker process.",
      "- Live gateway receipt-to-publish after the change: p50 about 1.1 ms, p99 about 6.8 ms (n=2033, one M15 bar close observed with max 10.2 ms); a systematic series across many bar closes has NOT been collected.",
      "- The figures describe this machine, this Chrome and this load; they are not a guarantee. There is no zero-latency claim.", ""]
(ROOT / "docs" / "qa" / "LATENCY_REPORT.md").write_text("\n".join(L), encoding="utf-8")
print("\n".join(L)[:2500])
